SET data = jsonb_set(jsonb_set(data, '{role}', $json${"en": "Founder & CEO | Chief Shariah Advisor", "ur": "بانی و سی ای او | چیف شریعہ ایڈوائزر"}$json$::jsonb), '{bio}', $json${"en": "Dr. Zeeshan Rais Khattak is a distinguished academic and the driving force behind Al-Ihkam. Currently serving as an Assistant Professor of Islamic Studies at Bahria University, Islamabad, he combines a deep scholarly understanding of Shariah with a rigorous, research-driven approach to modern finance.\n\nHis academic grounding in Islamic finance is anchored by a specialised M.Sc. in Islamic Banking and Finance and a Ph.D. in Islamic Studies. His doctoral research, on non-Shariah-compliant financial transactions and their socio-economic impact, forms the intellectual backbone of our advisory services. His M.Phil. research, an analysis of State Bank policies on Islamic banking, gives him a macro-level understanding of financial regulation.\n\nDr. Khattak is an active contributor to contemporary Islamic finance discourse, with peer-reviewed articles on critical topics including the socio-economic impact of Riba, the Shariah compliance of cryptocurrency and business ethics in Islam.\n\nUnder his leadership, Al-Ihkam delivers Shariah-compliant solutions that are not only academically rigorous and ethically sound but also practically viable for the modern global economy.", "ur": "ڈاکٹر ذیشان رئیس خٹک ایک ممتاز ماہرِ تعلیم اور الاحکام کے روحِ رواں ہیں۔ آپ اس وقت بحریہ یونیورسٹی اسلام آباد میں اسلامیات کے اسسٹنٹ پروفیسر ہیں اور شریعت کے گہرے علمی فہم کو جدید مالیات کے بارے میں تحقیق پر مبنی، باریک بین طرزِ فکر کے ساتھ یکجا کرتے ہیں۔\n\nاسلامی مالیات میں آپ کی علمی بنیاد اسلامی بینکاری و مالیات میں خصوصی ایم ایس سی اور اسلامیات میں پی ایچ ڈی پر قائم ہے۔ آپ کی ڈاکٹریٹ تحقیق، جو غیر شرعی مالی معاملات اور ان کے سماجی و معاشی اثرات پر ہے، ہماری مشاورتی خدمات کی فکری بنیاد ہے۔ اسٹیٹ بینک کی اسلامی بینکاری سے متعلق پالیسیوں کے تجزیے پر مبنی آپ کی ایم فل تحقیق آپ کو مالیاتی ضوابط کا وسیع تر فہم فراہم کرتی ہے۔\n\nڈاکٹر خٹک عصری اسلامی مالیاتی مباحث میں سرگرم حصہ لیتے ہیں۔ ربا کے سماجی و معاشی اثرات، کرپٹو کرنسی کی شرعی حیثیت اور اسلام میں کاروباری اخلاقیات جیسے اہم موضوعات پر آپ کے تحقیقی مقالات ہم جائزہ جرائد میں شائع ہو چکے ہیں۔\n\nآپ کی قیادت میں الاحکام ایسے شریعت سے ہم آہنگ حل فراہم کرتا ہے جو نہ صرف علمی طور پر مضبوط اور اخلاقی طور پر درست ہیں بلکہ جدید عالمی معیشت میں عملی طور پر قابلِ عمل بھی ہیں۔"}$json$::jsonb),
    updated_at = now()
WHERE slug = 'zeeshan-rais-khattak';
